def main():
 old_hashes={p.name:sha(p) for p in OLD.iterdir() if p.is_file()}
 frozen=load(OLD/'raw-work-concordance.json');assert sum(len(r['works']) for r in frozen)==1072
 works=read('works');allkeys={r['queue_record']['source_key'][2:] for r in frozen}
 for r in frozen:assert r['works']==[w for w in works if w['first_author_key']==r['queue_record']['source_key'][2:]]
 ds=read('dissertations');dated={d['dissertation_id'] for d in ds if d['in_analysis']=='True' and d['year']};assert len(dated)==6794
 names=set(ADD);old=load(OLD/'review.json');prior={r['name']:r for r in old['records'] if r['name'] in names}
 own={r['queue_record']['name']:r['works'] for r in frozen if r['queue_record']['name'] in names}
 keys={w['work_id'] for rows in own.values() for w in rows};assert sum(map(len,own.values()))==174
 tids={k:set() for k in keys}
 for c in read('citations'):
  if c['work_id'] in keys and c['dissertation_id'] in dated:tids[c['work_id']].add(c['dissertation_id'])
 oldsets=load(OLD/'dated-citation-sets.json')['per_work'];assert all(sorted(v)==oldsets[k] for k,v in tids.items())
 oldsources=load(OLD/'sources.json')['sources'];needed={s for r in prior.values() for d in r['work_decisions'] for s in d['source_ids']}
 sources=[s for s in oldsources if s['id'] in needed]+S;ids={s['id'] for s in sources};assert len(ids)==len(sources)
 records=[];counts=[];sets={}
 for name,cfg in ADD.items():
  pr=prior[name];ws=own[name];pos=set(pr['confirmed_selected_work_indices'])|set(cfg['positive']);foreign=set(pr['confirmed_foreign_work_indices'])|set(cfg['foreign']);assert not pos&foreign
  union=lambda ii:set().union(*(tids[ws[i]['work_id']] for i in ii)) if ii else set()
  raw=union(range(len(ws)));positive=union(pos);optimistic=union(set(range(len(ws)))-foreign)
  assert len(raw)==pr['frozen_dated_key_count'];assert (len(positive),len(optimistic))==cfg['expected']
  decisions=[]
  for i,w in enumerate(ws):
   previous=pr['work_decisions'][i];state='confirmed_selected_person' if i in pos else 'confirmed_foreign_person' if i in foreign else 'held_not_assigned_in_selected_identity_count'
   ss=cfg['positive'].get(i,cfg['foreign'].get(i,previous['source_ids']));assert set(ss)<=ids
   notes='Title/author attribution only; frozen year, kind, container and count fields are not repaired. Bibliography presence does not prove complete reading or influence.' if i in pos or i in foreign else 'Explicitly unassigned after the bounded positive/upper-bound stopping criterion; not declared false. Ambiguous fragments, generic containers, OCR/date conflicts and unchecked title families remain held.'
   if name=='Charles Taylor' and i in [11,15]:notes+=' Taylor is the central essay author and a legitimate credited volume contributor; Gutmann edits and other commentators retain their authorship.'
   if name=='Charles Taylor' and i==1:notes+=' Philosophical Arguments appears as 1995 book in primary bibliography, while this row says 1973/article; not used.'
   if name=='Peter Brown' and i==47:notes+=' French publisher dates translation 2016, while this frozen French-title row gives 2012, the English publication year; identity family only.'
   decisions.append(dict(index=i,raw_record=w,dated_dissertation_count=len(tids[w['work_id']]),identity_count_decision=state,source_ids=ss,prior_decision=previous['identity_count_decision'],rationale=notes))
  counts.append(dict(name=name,source_key=pr['source_key'],work_records=len(ws),frozen_dated_key_count=len(raw),prior_positive_lower_bound=pr['confirmed_selected_person_count'],prior_optimistic_upper_bound=pr['optimistic_person_upper_bound'],confirmed_selected_person_lower_bound=len(positive),optimistic_person_upper_bound=len(optimistic),positive_work_rows=len(pos),confirmed_foreign_work_rows=len(foreign),held_work_rows=len(ws)-len(pos)-len(foreign),decision=cfg['decision'],resolved_person_id=cfg['person_id'],layer=cfg['layer']))
  sets[name]=dict(frozen_dissertation_ids=sorted(raw),confirmed_selected_dissertation_ids=sorted(positive),optimistic_dissertation_ids=sorted(optimistic),confirmed_foreign_work_union_ids=sorted(union(foreign)))
  records.append(dict(name=name,source_key=pr['source_key'],resolved_person_id=cfg['person_id'],existing_person_id=pr['existing_person_id'],decision=cfg['decision'],layer=cfg['layer'],confirmed_selected_work_indices=sorted(pos),confirmed_foreign_work_indices=sorted(foreign),work_decisions=decisions,authority_limit='Identity is established through specific works and primary institutional/publisher or catalogue attribution, not a common-name alias or unverified QID. Existing person IDs are reuse targets, not claims of a raw-key identity merge.',limits=['Selected positive lower bound is not a complete author total.','Optimistic upper bound assigns every held row to the intended person; only confirmed foreign rows are excluded.','Dated means in_analysis=True with any nonempty dissertation year; original 6794 population retained.','No summed work counts, all-authorship substitution, raw-key merge, raw count/title/date repair, or citation-to-influence inference.']))
 assert old_hashes=={p.name:sha(p) for p in OLD.iterdir() if p.is_file()}
 manifest=dict(x.split('  ',1)[::-1] for x in (REL/'SHA256SUMS').read_text().splitlines())
 rh={n:sha(REL/n) for n in ['works.csv.gz','citations.csv.gz','dissertations.csv.gz','people.csv.gz','authorship.csv.gz']};assert all(manifest[n]==h for n,h in rh.items())
 dump('sources.json',dict(checked_on=DATE,sources=sources))
 dump('review.json',dict(checked_on=DATE,baseline='addendum to frozen 21-case classification review; no earlier decision file overwritten',threshold='Strictly more than 100 for this other-history/theory queue; Canadian-history focus is not inferred from birthplace.',records=records))
 dump('count-witnesses.json',dict(checked_on=DATE,dated_population=len(dated),scope='Exact frozen first-author work keys; dated dissertation ID UNION. Lower=confirmed intended work rows; upper=all rows except positively confirmed foreign works.',records=counts))
 dump('dated-citation-sets.json',dict(checked_on=DATE,per_work={k:sorted(v) for k,v in sorted(tids.items())},per_person=sets))
 dump('additive-queue.json',dict(checked_on=DATE,baseline_revision='1.188',target_revision='1.189',records=[c for c in counts if c['decision'].startswith('eligible_')]))
 dump('validation.json',dict(status='pass',checked_on=DATE,original_21_cases=21,frozen_work_rows_all_cases=1072,all_1072_work_rows_equal_release=True,reviewed_work_rows=174,all_174_have_explicit_decision=True,dated_population=len(dated),dated_per_work_sets_equal_frozen_review=True,old_artifacts_unchanged=old_hashes,release_sha256_verified=rh,new_shared_mutations=False,results=counts))
 print(json.dumps(counts,indent=2))
if __name__=='__main__':main()
